package it.ovs.wifidashboard;
import android.app.Activity;
import android.os.*;
import android.content.*;
import android.net.*;
import android.net.wifi.*;
import android.graphics.Color;
import android.view.*;
import android.widget.*;
import java.net.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import javax.net.ssl.HttpsURLConnection;

public class MainActivity extends Activity {
 final Handler ui=new Handler(Looper.getMainLooper());
 final ExecutorService pool=Executors.newFixedThreadPool(5);
 final String[] defaults={"itemoptixpreprod2.checkpointsystems.com","api-ovspp.eus1.itemoptix.com"};
 WifiManager wifi; ConnectivityManager cm; TextView live,results,scan,logs; Meter[] meters=new Meter[4]; Trend trend; Trend[] latency=new Trend[3]; int roams=0; EditText extra; LinearLayout root; boolean active=false; int gen=0; String previous=""; StringBuilder history=new StringBuilder();
 final Map<String,Stats> stats=new HashMap<>();
 class Stats {volatile double last=Double.NaN,loss=Double.NaN; int sent,ok; double sum,min=Double.MAX_VALUE,max,jitter,prev=-1; int pairs; synchronized String add(double v){sent++;last=v>=0?v:Double.NaN;if(v>=0){ok++;sum+=v;min=Math.min(min,v);max=Math.max(max,v);if(prev>=0){jitter+=Math.abs(v-prev);pairs++;}prev=v;}else prev=-1;loss=100.0*(sent-ok)/sent;return String.format(Locale.US,"ICMP %s | loss %.1f%% (%d/%d)\nmin/avg/max %s | jitter %s",v<0?"timeout":v+" ms",100.0*(sent-ok)/sent,sent-ok,sent,ok==0?"N/D":String.format(Locale.US,"%.1f/%.1f/%.1f ms",min,sum/ok,max),pairs==0?"N/D":String.format(Locale.US,"%.1f ms",jitter/pairs));}}
 TextView panel(String s){TextView t=new TextView(this);t.setText(s);t.setTextColor(0xffd7e5ef);t.setTextSize(14);t.setTypeface(android.graphics.Typeface.DEFAULT);t.setPadding(18,18,18,18);t.setBackgroundColor(0xff172333);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,6,0,6);root.addView(t,lp);return t;}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);root.addView(b);b.setOnClickListener(v->r.run());}
 public void onCreate(Bundle b){super.onCreate(b);wifi=(WifiManager)getApplicationContext().getSystemService(WIFI_SERVICE);cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(16,16,16,16);root.setBackgroundColor(0xff0b111b);scroll.addView(root);setContentView(scroll);TextView title=panel("OVS WIFI DASHBOARD PRO");title.setTextColor(0xff22d3ee);title.setTextSize(22);dashboard();live=panel("Wi-Fi live");extra=new EditText(this);extra.setHint("FQDN aggiuntivo (opzionale)");extra.setSingleLine(true);root.addView(extra);button("AVVIA MONITOR",()->start());button("STOP",()->stop());results=panel("PING / DNS / TCP / HTTPS");button("SCANSIONA ACCESS POINT",()->scan());scan=panel("RF scanner");logs=panel("EVENT LOG");button("ESPORTA LOG TXT",()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("text/plain");i.putExtra(Intent.EXTRA_TITLE,"wifi-console.txt");startActivityForResult(i,9);});requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION},1);}

 void dashboard(){String[] names={"SIGNAL STRENGTH","LINK SPEED","GATEWAY RTT","PACKET LOSS"};String[] units={"dBm","Mbps","ms","%"};double[] lo={-90,0,0,0},hi={-30,1200,100,100};for(int row=0;row<2;row++){LinearLayout line=new LinearLayout(this);root.addView(line);for(int j=0;j<2;j++){int i=row*2+j;meters[i]=new Meter(names[i],units[i],lo[i],hi[i],i);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(150),1);lp.setMargins(4,4,4,4);line.addView(meters[i],lp);}}trend=new Trend("RSSI HISTORY / dBm",-90,-30);root.addView(trend,new LinearLayout.LayoutParams(-1,dp(180)));String[] labels={"GATEWAY RTT / ms","CHECKPOINT RTT / ms","ITEMOPTIX RTT / ms"};for(int i=0;i<3;i++){latency[i]=new Trend(labels[i],0,100);root.addView(latency[i],new LinearLayout.LayoutParams(-1,dp(145)));}}
 int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 class Meter extends View{android.graphics.Paint p=new android.graphics.Paint(3);String name,unit;double low,high,value=Double.NaN;int type;Meter(String n,String u,double l,double h,int t){super(MainActivity.this);name=n;unit=u;low=l;high=h;type=t;}void set(double v){value=v;invalidate();}protected void onDraw(android.graphics.Canvas c){float w=getWidth(),h=getHeight();c.drawColor(0xff172333);p.setTextAlign(android.graphics.Paint.Align.CENTER);p.setColor(0xffb0c4d8);p.setTextSize(dp(11));c.drawText(name,w/2,dp(20),p);float r=Math.min(w*.37f,h*.34f),cx=w/2,cy=h*.63f;android.graphics.RectF a=new android.graphics.RectF(cx-r,cy-r,cx+r,cy+r);p.setStyle(android.graphics.Paint.Style.STROKE);p.setStrokeWidth(dp(8));p.setStrokeCap(android.graphics.Paint.Cap.ROUND);p.setColor(0xff34445a);c.drawArc(a,180,180,false,p);int col=0xff4ade80;if(type==1)col=0xff38bdf8;if(type==0&&value<-67||type==2&&value>30||type==3&&value>1)col=0xfffbbf24;if(type==0&&value<-75||type==2&&value>100||type==3&&value>5)col=0xfff87171;if(Double.isFinite(value)){p.setColor(col);c.drawArc(a,180,(float)(180*Math.max(0,Math.min(1,(value-low)/(high-low)))),false,p);}p.setStyle(android.graphics.Paint.Style.FILL);p.setColor(Double.isFinite(value)?col:0xff94a3b8);p.setTextSize(dp(25));c.drawText(Double.isFinite(value)?String.format(Locale.US,type<2?"%.0f":"%.1f",value):"N/D",cx,cy,p);p.setTextSize(dp(12));c.drawText(unit,cx,cy+dp(20),p);}}
 class Trend extends View{final ArrayList<Double> values=new ArrayList<>();final android.graphics.Paint p=new android.graphics.Paint(3);String name;double lo,hi;Trend(String n,double l,double h){super(MainActivity.this);name=n;lo=l;hi=h;}void add(double v){values.add(v);if(values.size()>60)values.remove(0);invalidate();}protected void onDraw(android.graphics.Canvas c){c.drawColor(0xff131e2d);float w=getWidth(),h=getHeight(),left=dp(40),top=dp(30),bottom=h-dp(15);double max=hi;for(double v:values)if(Double.isFinite(v))max=Math.max(max,v);p.setColor(0xff22d3ee);p.setTextSize(dp(12));c.drawText(name,dp(10),dp(18),p);for(int i=0;i<=4;i++){float y=top+(bottom-top)*i/4;p.setColor(0xff34445a);p.setStrokeWidth(1);c.drawLine(left,y,w-dp(8),y,p);p.setColor(0xff94a3b8);p.setTextSize(dp(10));c.drawText(String.format(Locale.US,"%.0f",max-(max-lo)*i/4),dp(4),y,p);}p.setColor(0xff4ade80);p.setStrokeWidth(dp(2));float px=0,py=0;boolean prev=false;for(int i=0;i<values.size();i++){double v=values.get(i);float x=left+(w-left-dp(8))*i/59;if(!Double.isFinite(v)){prev=false;continue;}float y=bottom-(bottom-top)*(float)Math.max(0,Math.min(1,(v-lo)/(max-lo)));if(prev)c.drawLine(px,py,x,y,p);else c.drawCircle(x,y,dp(2),p);px=x;py=y;prev=true;}}}
 Network network(){for(Network n:cm.getAllNetworks()){NetworkCapabilities c=cm.getNetworkCapabilities(n);if(c!=null&&c.hasTransport(NetworkCapabilities.TRANSPORT_WIFI))return n;}return null;}
 String gateway(LinkProperties p){if(p!=null)for(RouteInfo r:p.getRoutes())if(r.isDefaultRoute()&&r.getGateway() instanceof Inet4Address)return r.getGateway().getHostAddress();return "";}
 int channel(int f){if(f==2484)return 14;if(f>=2412&&f<=2472)return (f-2407)/5;if(f>=5955&&f<=7115)return (f-5950)/5;if(f>=5000&&f<5955)return (f-5000)/5;return -1;}
 void log(String s){String line=new java.text.SimpleDateFormat("HH:mm:ss",Locale.US).format(new Date())+" "+s;history.append(line).append('\n');logs.setText(history.substring(Math.max(0,history.length()-5000)));}
 void start(){if(active)return;Network n=network();if(n==null){log("Wi-Fi non connesso");return;}if(!cm.bindProcessToNetwork(n)){log("Binding Wi-Fi fallito");return;}active=true;gen++;stats.clear();previous="";roams=0;trend.values.clear();for(Trend t:latency)t.values.clear();getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);tick(gen,n);}
 void stop(){active=false;gen++;cm.bindProcessToNetwork(null);getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}
 double ping(String ip){java.lang.Process p=null;try{p=new ProcessBuilder("/system/bin/ping","-c","1","-W","1",ip).redirectErrorStream(true).start();try(BufferedReader r=new BufferedReader(new InputStreamReader(p.getInputStream()))){String s;while((s=r.readLine())!=null){java.util.regex.Matcher m=java.util.regex.Pattern.compile("time[=<]\\s*([0-9.]+)").matcher(s);if(m.find())return Double.parseDouble(m.group(1));}}}catch(Exception e){}finally{if(p!=null)p.destroy();}return -1;}
 String probe(Network n,String host,boolean web,Stats st){StringBuilder s=new StringBuilder(host+"\n");try{InetAddress[] ips=n.getAllByName(host);s.append("DNS: ").append(Arrays.toString(ips)).append('\n');InetAddress ip=ips[0];for(InetAddress a:ips)if(a instanceof Inet4Address){ip=a;break;}s.append(st.add(ping(ip.getHostAddress()))).append('\n');if(web){try(Socket sock=n.getSocketFactory().createSocket()){long t=SystemClock.elapsedRealtime();sock.connect(new InetSocketAddress(ip,443),2000);s.append("TCP 443 OK ").append(SystemClock.elapsedRealtime()-t).append(" ms\n");}catch(Exception e){s.append("TCP 443 KO\n");}HttpsURLConnection c=null;try{c=(HttpsURLConnection)n.openConnection(new URL("https://"+host+"/"));c.setConnectTimeout(2500);c.setReadTimeout(2500);c.setInstanceFollowRedirects(false);c.setRequestMethod("HEAD");int code=c.getResponseCode();s.append("TLS OK / HTTP ").append(code).append(" (server raggiunto)\n");}catch(Exception e){s.append("HTTPS KO: ").append(e.getClass().getSimpleName()).append('\n');}finally{if(c!=null)c.disconnect();}}}catch(Exception e){s.append("DNS KO / test non eseguito\n");}return s.toString();}
 void tick(int g,Network n){if(!active||g!=gen)return;if(!n.equals(network())){stop();log("Rete Wi-Fi cambiata: riavviare monitor");return;}WifiInfo w=wifi.getConnectionInfo();LinkProperties p=cm.getLinkProperties(n);String gw=gateway(p);String b=w.getBSSID();if(b!=null&&!b.equals(previous)){if(!previous.isEmpty())roams++;log("BSSID "+previous+" -> "+b);previous=b;}meters[0].set(w.getRssi()>-127?w.getRssi():Double.NaN);meters[1].set(w.getLinkSpeed()>0?w.getLinkSpeed():Double.NaN);trend.add(w.getRssi()>-127?w.getRssi():Double.NaN);String standard=Build.VERSION.SDK_INT>=30?String.valueOf(w.getWifiStandard()):"N/D";live.setText("LIVE WLAN\nSSID "+w.getSSID()+"\nBSSID "+b+"\nRSSI "+w.getRssi()+" dBm\nFrequency "+w.getFrequency()+" MHz | CH "+channel(w.getFrequency())+"\nLink "+w.getLinkSpeed()+" Mbps\nStandard (Android ID) "+standard+"\nIP/prefix "+(p==null?"N/D":p.getLinkAddresses())+"\nGateway "+gw+"\nDNS "+(p==null?"N/D":p.getDnsServers())+"\nRoaming events: "+roams+"\nNoise/SNR/retries: N/D");ArrayList<String> hosts=new ArrayList<>();if(!gw.isEmpty())hosts.add(gw);hosts.addAll(Arrays.asList(defaults));String x=extra.getText().toString().trim();if(x.matches("[A-Za-z0-9.-]+")&&!hosts.contains(x))hosts.add(x);ArrayList<Future<String>> jobs=new ArrayList<>();for(String host:hosts){Stats st=stats.computeIfAbsent(host,k->new Stats());jobs.add(pool.submit(()->probe(n,host,!host.equals(gw),st)));}pool.submit(()->{StringBuilder out=new StringBuilder("CONNECTIVITY MONITOR\n");if(gw.isEmpty())out.append("IPv4 gateway N/D\n");for(Future<String> f:jobs)try{out.append('\n').append(f.get());}catch(Exception e){out.append("Test interrotto\n");}ui.post(()->{if(active&&g==gen){Stats gs=stats.get(gw);meters[2].set(gs==null?Double.NaN:gs.last);meters[3].set(gs==null?Double.NaN:gs.loss);String[] targets={gw,defaults[0],defaults[1]};for(int i=0;i<3;i++){Stats st=stats.get(targets[i]);latency[i].add(st==null?Double.NaN:st.last);}results.setText(out);log(out.toString());ui.postDelayed(()->tick(g,n),1000);}});});}
 void scan(){try{boolean requested=wifi.startScan();List<ScanResult> list=wifi.getScanResults();list.sort((a,b)->Integer.compare(b.level,a.level));StringBuilder s=new StringBuilder("RF SCANNER (cache Android; nuova scansione "+(requested?"richiesta":"non disponibile")+")\n");for(ScanResult a:list)s.append(a.SSID).append(" | ").append(a.BSSID).append("\n").append(a.level).append(" dBm | CH ").append(channel(a.frequency)).append(" | ").append(a.frequency).append(" MHz | width ID ").append(a.channelWidth).append("\n").append(a.capabilities).append("\n\n");scan.setText(s);}catch(Exception e){scan.setText("Verificare permesso posizione precisa e localizzazione attiva");}}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==9&&c==RESULT_OK&&d!=null)try(OutputStream o=getContentResolver().openOutputStream(d.getData())){o.write(history.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){log("Export KO");}}
 protected void onDestroy(){stop();pool.shutdownNow();super.onDestroy();}
}
